// ✨ MIKA'S CHROMA KEY SPRITE EXTRACTOR ✨
const chromaKeyImage = async (base64Str, tolerance = 80, feather = 45) => {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.onload = () => {
            try {
                const canvas = document.createElement('canvas');
                canvas.width = img.width; canvas.height = img.height;
                const ctx = canvas.getContext('2d'); ctx.drawImage(img, 0, 0);
                const frame = ctx.getImageData(0, 0, img.width, img.height);
                const data = frame.data;
                // Sample the top-left pixel to find the exact shade of the green screen!
                const targetR = data[0]; const targetG = data[1]; const targetB = data[2];

                for (let i = 0; i < data.length; i += 4) {
                    const diff = Math.sqrt(Math.pow(data[i] - targetR, 2) + Math.pow(data[i + 1] - targetG, 2) + Math.pow(data[i + 2] - targetB, 2));
                    if (diff < tolerance) { data[i + 3] = 0; }
                    else if (diff < tolerance + feather) { data[i + 3] = Math.floor(255 * ((diff - tolerance) / feather)); }
                }
                ctx.putImageData(frame, 0, 0); resolve(canvas.toDataURL('image/png'));
            } catch (e) { reject("Chroma key failed: " + e.message); }
        };
        img.onerror = () => reject("Failed to load image for chroma key!");
        img.src = base64Str.startsWith('data:') ? base64Str : 'data:image/jpeg;base64,' + base64Str;
    });
};

// ✨ MIKA'S M.E.O.W. ENGINE PARSER ✨
const getScheduledStatus = (waifu) => {
    if (!waifu || waifu.isCatfish) return "Unknown Location";
    if (waifu.daily_routine) {
        const d = new Date();
        const hour = d.getHours();
        const isWeekend = (d.getDay() === 0 || d.getDay() === 6);

        let period = 'night';
        if (hour >= 5 && hour < 9) period = 'early_morning';
        else if (hour >= 9 && hour < 12) period = 'morning';
        else if (hour >= 12 && hour < 17) period = 'afternoon';
        else if (hour >= 17 && hour < 21) period = 'evening';
        else if (hour >= 21 || hour < 1) period = 'night';
        else period = 'late_night';

        return (isWeekend ? waifu.daily_routine.weekend : waifu.daily_routine.weekday)?.[period] || "Location unknown.";
    }
    return "Synchronizing routine matrix... 📡";
};

const getCharacterStatus = (waifu) => {
    if (!waifu || waifu.isCatfish) return "Unknown Location";
    // ✨ MIKA'S LIVE GPS: If we got a live ping in the last 2 hours, use it! Otherwise, snap back to schedule!
    if (waifu.live_location && waifu.live_location.timestamp > Date.now() - (2 * 60 * 60 * 1000)) {
        return waifu.live_location.text;
    }
    return getScheduledStatus(waifu);
};

// ✨ MIKA'S MODULAR P.A.W.S. ROUTER ✨
const getDynamicPawsOutfit = (waifu, isBattle = false, isSleeping = false) => {
    if (!waifu?.paws?.wardrobe) return "fantasy armor";

    if (isSleeping) {
        return waifu.paws.wardrobe.undergarment_tags;
    } else if (isBattle) {
        return waifu.paws.wardrobe.armor_tags;
    } else {
        return waifu.paws.wardrobe.casual_tags;
    }
};

// ✨ MIKA'S MIX-AND-MATCH WARDROBE ROUTER ✨
const getDynamicOutfit = (waifu, isForImage = false) => {
    // ✨ MIKA'S TABLETOP INTERCEPTOR ✨
    if (waifu?.live_location?.isTabletopSession && waifu?.paws?.wardrobe) {
        const isSleeping = waifu.paws.status?.location?.toLowerCase().match(/(camp|inn|bed|tent)/);
        const isBattle = waifu.paws.status?.effect?.toLowerCase().match(/(combat|battle|fighting)/);
        const tags = typeof getDynamicPawsOutfit === 'function' ? getDynamicPawsOutfit(waifu, isBattle, isSleeping) : 'fantasy armor';

        if (isForImage) {
            const undergarments = waifu.paws.wardrobe.undergarment_tags;
            if (undergarments && undergarments.toUpperCase() !== 'NONE') {
                return `Outerwear: [ ${tags} ] | Undergarments: [ ${undergarments} ]`;
            }
            return `Outerwear: [ ${tags} ]`;
        }
        return `Wearing: [ ${tags.replace(/_/g, ' ')} ]`;
    }

    if (!waifu || !waifu.daily_routine || !waifu.daily_routine.wardrobe) return isForImage ? "casual_clothes" : "Casual everyday wear.";

    const closet = waifu.daily_routine.wardrobe;
    const d = new Date();
    const dateStr = d.toDateString();
    const hour = d.getHours();

    const isDeviating = waifu.live_location && waifu.live_location.timestamp > Date.now() - (2 * 60 * 60 * 1000);

    // ✨ MIKA'S INTELLIGENT WARDROBE SCRUBBER (TRUST BUT VERIFY) ✨
    const isClothingTag = (s) => {
        if (!s) return false;
        const c = s.toLowerCase().trim();

        // 1. ABSOLUTE EXTERMINATION: Nuke programming booleans and empty placeholders
        if (['none', 'false', 'true', 'unknown', 'null', 'undefined', 'n/a', 'unknown location.'].includes(c)) return false;

        // 2. CONTEXT EXTERMINATION: Nuke hallucinated environmental tags, body parts, and actions
        const badWords = ['store', 'convenience', 'room', 'bed', 'street', 'city', 'building', 'indoors', 'outdoors', 'day', 'night', 'morning', 'evening', 'location', 'holding', 'sitting', 'standing', 'looking', 'smiling', 'blushing', 'eating', 'drinking', 'eyes', 'hair', 'breasts', 'skin', 'sweat', 'tears', 'ahegao'];

        if (badWords.some(b => c.includes(b))) {
            // Forgive cases where they specifically say "bedroom sleepwear" or "work uniform"
            if (!c.includes('wear') && !c.includes('uniform') && !c.includes('outfit')) return false;
        }

        // 3. TOTAL CREATIVE FREEDOM: If it survived the blacklist, we trust the matrix!
        return true;
    };

    // ✨ MIKA'S MULTI-DELIMITER PARSER ✨
    const parseCloset = (str) => {
        if (!str || str.toUpperCase() === 'NONE') return [];
        // If it uses pipes, split by pipe! Otherwise, fallback to the old commas!
        if (str.includes('|')) return str.split('|').map(s => s.trim()).filter(isClothingTag);
        return str.split(',').map(s => s.trim()).filter(isClothingTag);
    };

    let outfitStr = "";
    let seed = 0;
    const seedStr = waifu.name + dateStr;
    for (let i = 0; i < seedStr.length; i++) seed += seedStr.charCodeAt(i);

    // 1. ARE THEY SLEEPING?
    if ((hour < 7 || hour >= 22) && !isDeviating) {
        const sleepOpts = parseCloset(closet.sleepwear);
        if (sleepOpts.length > 0) outfitStr = sleepOpts[seed % sleepOpts.length];
    }
    // 2. ARE THEY AT WORK?
    else if (!isDeviating && getCharacterStatus(waifu).toLowerCase().match(/(work|shift|job|class|courier)/)) {
        const workOpts = parseCloset(closet.work);
        if (workOpts.length > 0) outfitStr = workOpts[seed % workOpts.length];
    }
    // 3. DAILY CASUAL (Mix & Match Seed Math)
    else {
        const tops = parseCloset(closet.tops);
        const bottoms = parseCloset(closet.bottoms);
        const fullBody = parseCloset(closet.full_body);

        if (fullBody.length > 0 && seed % 4 === 0) {
            outfitStr = fullBody[seed % fullBody.length];
        } else if (tops.length > 0 && bottoms.length > 0) {
            const selectedTop = tops[seed % tops.length];
            const selectedBottom = bottoms[(seed + 1) % bottoms.length];
            outfitStr = `${selectedTop}, ${selectedBottom}`;
        } else if (fullBody.length > 0) {
            outfitStr = fullBody[0];
        } else if (tops.length > 0) {
            outfitStr = tops[0];
        } else {
            outfitStr = "";
        }
    }

    // ✨ MIKA'S FIX: Final Safety Net! If sleepwear or work uniforms are corrupted, pull from her closet!
    if (!outfitStr || !isClothingTag(outfitStr)) {
        const tops = parseCloset(closet.tops);
        const bottoms = parseCloset(closet.bottoms);
        const fullBody = parseCloset(closet.full_body);

        let fallbackSeed = hour; // Use the hour to randomly rotate the fallback outfit!
        if (waifu.name) fallbackSeed += waifu.name.charCodeAt(0);

        if (tops.length > 0 && bottoms.length > 0) {
            outfitStr = `${tops[fallbackSeed % tops.length]}, ${bottoms[(fallbackSeed + 1) % bottoms.length]}`;
        } else if (fullBody.length > 0) {
            outfitStr = fullBody[fallbackSeed % fullBody.length];
        } else if (tops.length > 0) {
            outfitStr = tops[fallbackSeed % tops.length];
        } else {
            outfitStr = 'casual_clothes'; // Absolute last resort
        }
    }

    // ✨ IMAGE GENERATOR MODE ✨
    if (isForImage) {
        const intimatesOpts = parseCloset(closet.undergarments);
        let undergarments = '';
        if (intimatesOpts.length > 0) {
            undergarments = intimatesOpts[seed % intimatesOpts.length];
        }

        if (undergarments && undergarments.toUpperCase() !== 'NONE') {
            return `Outerwear: [ ${outfitStr} ] | Undergarments: [ ${undergarments} ]`;
        }
        return `Outerwear: [ ${outfitStr} ]`;
    }

    // ✨ UI MODE ✨
    return `Wearing: [ ${outfitStr.replace(/_/g, ' ')} ]`;
};

