        // ✨ MIKA'S FIX: Parse the global prefix WITHOUT scrubbing it!
        const prefixTags = state.useLocalDreamPrefix ? [] : parseTags(state.imagePrefix || imagePrefix).slice(0, 10);

        let coreTags = parseTags(coreString);
        let dynamicTags = parseTags(dynamicString);

        // MIKA'S LEGACY SCRUBBER: Only scrub the LLM/Legacy data so we don't double up!
        const legacyBans = ['masterpiece', 'best quality'];
        coreTags = coreTags.filter(t => !legacyBans.includes(t));
        dynamicTags = dynamicTags.filter(t => !legacyBans.includes(t));

        // ✨ MIKA'S GENDER-LOCK CENSOR ✨
        // Shreds conflicting LLM explicit tags before they hit the diffuser!
        const isMale = coreTags.some(t => t.toLowerCase().includes('1boy') || t.toLowerCase().includes('male'));
        const isFemale = coreTags.some(t => t.toLowerCase().includes('1girl') || t.toLowerCase().includes('female'));

        if (isMale && !isFemale) {
            const femaleBans = ['1girl', 'girl', 'female', 'breasts', 'cleavage', 'panty', 'bikini', 'bra', 'skirt', 'waifu'];
            dynamicTags = dynamicTags.filter(tag => !femaleBans.some(b => tag.toLowerCase().includes(b)));
        } else if (isFemale && !isMale) {
            const maleBans = ['1boy', 'boy', 'male', 'penis', 'bulge'];
            dynamicTags = dynamicTags.filter(tag => !maleBans.some(b => tag.toLowerCase().includes(b)));
        }

        // Cap to 15 discrete tags per section after legacy/gender filtering
        coreTags = coreTags.slice(0, 15);
        dynamicTags = dynamicTags.slice(0, 15);

        const combined = [...prefixTags, ...coreTags, ...dynamicTags];

        // ✨ MIKA'S CUSTOM BANNED TAGS SCRUBBER ✨
        // If a generated tag matches ANY banned words/sub-terms, the ENTIRE tag is shredded.
        const bannedList = getActiveBannedTags();
        const safeTags = combined.filter(tag => !isTagBanned(tag, bannedList));

        return [...new Set(safeTags)].join(', ');
