    useEffect(() => {
        if (!layla) return;

        const manageOSQueue = async () => {
            try {
                const scheduled = await layla.chat.getScheduledChatMessages();
                if (!scheduled) return;

                const now = Date.now();
                let validLures = [];

                // 1. ✨ MIKA'S INSTANT ASSASSINATION PROTOCOL ✨
                // Layla's API keeps delivered messages forever. We MUST vaporize them 
                // the exact millisecond they detonate to free up the 10 OS slots!
                for (const s of scheduled) {
                    if (s.timestamp <= now) {
                        try { await layla.chat.cancelScheduledChatMessage(s.id); } catch (e) { }
                    } else {
                        validLures.push(s);
                    }
                }

                // 2. ✨ MIKA'S VIP BOUNCER (Hard cap at 10 to respect OS limits!) ✨
                if (validLures.length > 10) {
                    validLures.sort((a, b) => a.timestamp - b.timestamp);
                    const doomedLures = validLures.slice(10);
                    validLures = validLures.slice(0, 10);

                    for (const d of doomedLures) {
                        try { await layla.chat.cancelScheduledChatMessage(d.id); } catch (e) { }
                    }
                } else {
                    validLures.sort((a, b) => a.timestamp - b.timestamp);
                }

                setScheduledLuresView(prev => prev !== null ? validLures : null);
            } catch (e) { }
        };

        manageOSQueue();
        const interval = setInterval(manageOSQueue, 10000); // Check every 10 seconds!
        return () => clearInterval(interval);
    }, [layla]);

