                    const isGm = m.isGm || (m.speakerName && (/mika|proxy|game\s*master|dungeon\s*master|\bdm\b|narrator|system/i.test(m.speakerName) || m.speakerName === 'M.I.K.A. Proxy'));
                    const sentences = (m.isSystemAction || isGm) ? [clean] : (clean.match(/[^.!?]+[.!?]+(\s|$)|[^.!?]+$/g) || [clean]);
                    const validSentences = sentences.map(s => s.trim()).filter(Boolean);
