    // ✨ MIKA'S SMART FRANCHISE NORMALIZER ✨
    const normalizeFranchise = (name) => {
        if (!name) return 'KNOWN CHARACTERS';
        let n = name.toUpperCase().trim();

        // Group all original character variants together
        if (n === 'ORIGINAL' || n === 'ORIGINAL CHARACTER' || n === 'OC' || n === 'NONE' || n === 'N/A' || n === 'UNKNOWN') return 'ORIGINAL CHARACTERS';

        // Catch common fragmented franchises & character-name fallbacks
        if (n.includes('TO LOVE') || n === 'YAMI' || n === 'GOLDEN DARKNESS') return 'TO LOVE-RU';
        if (n.includes('FATE/') || n.includes('FATE STAY')) return 'FATE SERIES';
        if (n.includes('PERSONA')) return 'PERSONA';
        if (n.includes('EVANGELION')) return 'EVANGELION';
        if (n.includes('NIER')) return 'NIER';
        if (n.includes('CYBERPUNK')) return 'CYBERPUNK';
        if (n.includes('FINAL FANTASY')) return 'FINAL FANTASY';
        if (n.includes('DRAGON BALL')) return 'DRAGON BALL';
        if (n.includes('POKEMON') || n.includes('POKÉMON')) return 'POKEMON';
        if (n.includes('STAR WARS')) return 'STAR WARS';
        if (n.includes('STREET FIGHTER')) return 'STREET FIGHTER';

        // Strip subtitles to dynamically group franchises (e.g., "Game: Subtitle" -> "Game")
        if (n.includes(':')) n = n.split(':')[0].trim();
        if (n.includes(' - ')) n = n.split(' - ')[0].trim();

        return n;
    };

