                    const msgs = chat.messages || [];
                    if (msgs.length === 0) return;

                    const lastMsg = msgs[msgs.length - 1];
                    if (lastMsg.role === 'user') return;

                    let consecutiveIdles = 0;
                    for (let i = msgs.length - 1; i >= 0; i--) {
                        if (msgs[i].isIdle) consecutiveIdles++;
                        else break;
                    }
                    if (consecutiveIdles >= 2) return; // ✨ 2-Strike Rule! No more triple-texting!

                    const isStaring = state.activeChatId === chatId && state.isBuddyOpen;

                    if (isStaring && state.buddyInput && state.buddyInput.trim().length > 0) return;

