                let tags = (v.tags || []).map(t => t.toLowerCase());
                if (!state.ttsUseForge && GACHASWIPE_TTS_PRESETS[v.id]) tags = [...tags, ...GACHASWIPE_TTS_PRESETS[v.id]];

