                detailedProfiles: state.detailedProfiles, diverseNames: state.diverseNames, isKnownCharacter: state.isKnownCharacter, isSurpriseMode: state.isSurpriseMode,
                selectedEngine: state.selectedEngine, selectedImageModel: state.selectedImageModel, autoResume: state.autoResume, autoSaveSwipes: state.autoSaveSwipes, selectedChara: state.selectedChara,
                recentNames: state.recentNames, genderPrefs: state.genderPrefs, msgThirst: state.msgThirst, queue: state.queue, useLaylaPersona: state.useLaylaPersona, customUserProfile: state.customUserProfile,
                hasSeenTutorial: state.hasSeenTutorial, seenTutorialVersion: state.seenTutorialVersion, dismissedUpdateVersion: state.dismissedUpdateVersion, hasCollectedFirstTutorialSpark: state.hasCollectedFirstTutorialSpark, collectedTutorialRewards: state.collectedTutorialRewards, ssrPityCount: state.ssrPityCount, enableAtmosphere: state.enableAtmosphere, enableMp3Compression: state.enableMp3Compression, cinematicChatBg: state.cinematicChatBg, showFullHistory: state.showFullHistory, appLanguage: state.appLanguage, pauseBetweenSwipes: state.pauseBetweenSwipes,
                chatContextLimit: state.chatContextLimit, groupChatContextLimit: state.groupChatContextLimit, chatProfileDetail: state.chatProfileDetail, groupProfileDetail: state.groupProfileDetail, tokenPreset: state.tokenPreset, chatStyleMode: state.chatStyleMode, groupChatStyleMode: state.groupChatStyleMode, actionTextColor: state.actionTextColor, proactiveOffline: state.proactiveOffline, proactiveIdle: state.proactiveIdle, proactiveFavoritesOnly: state.proactiveFavoritesOnly, enableMeowEngine: state.enableMeowEngine, enableSelfieAutonomy: state.enableSelfieAutonomy, enableProactiveSelfies: state.enableProactiveSelfies, syncSpeed: state.syncSpeed, hasSeenDevPreset: state.hasSeenDevPreset, groupChatFlow: state.groupChatFlow, groupChatPause: state.groupChatPause, backgroundSpooling: state.backgroundSpooling, recklessSaveMode: state.recklessSaveMode, autoUpdateLaylaCards: state.autoUpdateLaylaCards, customPresets: state.customPresets, activePresetId: state.activePresetId,
                spriteExplicitMode: state.spriteExplicitMode,
                monsterAestheticMode: state.monsterAestheticMode,
                imagePrefix: state.imagePrefix,
                bannedTags: state.bannedTags,
                bannedLyrics: state.bannedLyrics,
                pinnedChatBgs: state.pinnedChatBgs,
                minigameHighScore: state.minigameHighScore,
                selectedKnownCharCategories: state.selectedKnownCharCategories,
                knownCharCustomCategories: state.knownCharCustomCategories,
                startupScreen: state.startupScreen,
                gachaFansHubAd: state.gachaFansHubAd,
                gachaFansHubAdDate: state.gachaFansHubAdDate,
                gachaFansHubFeatured: state.gachaFansHubFeatured,
                gachaFansHubFeaturedDate: state.gachaFansHubFeaturedDate,
                gachaFansDiscovery: state.gachaFansDiscovery,
                discoveryThemeFilter: state.discoveryThemeFilter,
                discoveryCacheSize: state.discoveryCacheSize,
                silhouetteMode: state.silhouetteMode,
                sparkTokens: state.sparkTokens,
                hasSeenLateNightWarning: state.hasSeenLateNightWarning,
                hasSeenHubAd: state.hasSeenHubAd,
                hasSeenMeowAd: state.hasSeenMeowAd,
                hasSeenSysCtrlAd: state.hasSeenSysCtrlAd,
                hasSeenCardSyncAd: state.hasSeenCardSyncAd,
                hasSeenV28Ad: state.hasSeenV28Ad,
