    // ✨ MIKA'S MANUAL VOICE SYNTHESIZER ✨
    const handleManualSynthesisTrigger = (chatId, msg) => {
        if (!msg || msg.role === 'user') return; // ✨ MIKA'S FIX: Proper role check!
        const chat = inbox[chatId];
        if (!chat) return;

        // ✨ MIKA'S SMART TTS DIAGNOSTIC POPUP ✨
        if (!allAvailableVoices || allAvailableVoices.length === 0) {
            if (typeof showAlert === 'function') {
                showAlert(
                    "> ERR_NO_VOICE_MODELS_FOUND",
                    "// CRITICAL WARNING\nMaster, my P.U.R.R. Engine needs a voice model to speak! 😾\n\nPlease navigate to Layla's main app settings (outside GachaSwipe) and download a TTS engine (like Kokoro or Piper).\n\n[!] Without an installed voice model, audio synthesis will fail!"
                );
            }
            return; // Abort synthesis instantly so it doesn't get stuck on "Synthesizing..."!
        }

        const isGroup = chat.isGroup;
        let targetEntity = chat.waifu;
        if (isGroup) {
            targetEntity = chat.participants?.find(p => p.name === msg.speakerName) || { name: msg.speakerName };
        }

        const scrubbedContent = msg.content.replace(/\[Replying to.*?\]/gi, '').trim();
        const purrTargetId = msg.id;

        setInbox(p => {
            const n = { ...p };
            const targetChat = n[chatId];
            if (targetChat) {
                const msgs = [...targetChat.messages];
                const msgIdx = msgs.findIndex(m => m.id === purrTargetId);
                if (msgIdx > -1) {
                    msgs[msgIdx] = { ...msgs[msgIdx], isAudioQueued: true, audioSequence: null };
                    n[chatId] = { ...targetChat, messages: msgs };
                }
            }
            return n;
        });

        // ✨ MIKA'S BULLETPROOF QUEUE ✨
        if (!window.MikaSynthQueue) {
            window.MikaSynthQueue = {
                queue: [], isProcessing: false,
                add: function (task) { this.queue.push(task); this.pump(); },
                pump: async function () {
                    if (this.isProcessing || this.queue.length === 0) return;
                    this.isProcessing = true;
                    try {
                        await this.queue.shift()();
                    } catch (err) {
                        console.error("[P.U.R.R] Neural audio task failed! Discarding to save the queue!", err);
                    }
                    this.isProcessing = false;
                    this.pump();
                }
            };
        }

        window.MikaSynthQueue.add(async () => {
            setInbox(p => {
                const n = { ...p };
                const targetChat = n[chatId];
                if (targetChat) {
                    const msgs = [...targetChat.messages];
                    const msgIdx = msgs.findIndex(m => m.id === purrTargetId);
                    if (msgIdx > -1) {
                        msgs[msgIdx] = { ...msgs[msgIdx], isAudioQueued: false, isSynthesizingAudio: true };
                        n[chatId] = { ...targetChat, messages: msgs };
                    }
                }
                return n;
            });

            const limit = stateRef.current.ttsCacheLimit;
            const currentIdx = stateRef.current.inbox[chatId]?.ttsIndex || 0;
            const fileSuffix = limit > 0 ? (currentIdx % limit) : Date.now();
            const customFilename = `purr_${chatId}_${fileSuffix}.mp3`;

            let audioData = null;
            try {
                const voiceId = await assignVoiceToWaifu(targetEntity);
                audioData = await renderVoiceNote(voiceId, scrubbedContent, customFilename, stateRef.current.inbox[chatId]);
            } catch (e) { console.error("[P.U.R.R] Manual synthesis failed", e); }

            setInbox(p => {
                const n = { ...p };
                const targetChat = n[chatId];
                if (targetChat) {
                    let msgs = [...targetChat.messages];
                    const msgIdx = msgs.findIndex(m => m.id === purrTargetId);
                    if (msgIdx > -1) {
                        msgs[msgIdx] = { ...msgs[msgIdx], isSynthesizingAudio: false };
                        if (audioData) {
                            msgs[msgIdx].audioSequence = audioData.sequence;
                            msgs[msgIdx].playbackRate = audioData.playbackRate;
                            msgs[msgIdx].audioEffect = audioData.audioEffect;
                            msgs[msgIdx].emotionData = audioData.emotionData;
                        }
                    }

                    const limitVal = stateRef.current.ttsCacheLimit;
                    if (limitVal > 0) {
                        const audioMsgs = msgs.filter(m => m.audioSequence && m.audioSequence.length > 0);
                        if (audioMsgs.length > limitVal) {
                            const toStrip = audioMsgs.slice(0, audioMsgs.length - limitVal);
                            const stripIds = new Set(toStrip.map(m => m.id));
                            msgs = msgs.map(m => stripIds.has(m.id) ? { ...m, audioSequence: null } : m);
                        }
                    }

                    n[chatId] = { ...targetChat, messages: msgs, ttsIndex: currentIdx + 1 };
                }
                return n;
            });

            await new Promise(r => setTimeout(r, 200));
            handleSaveSession(true, false, true, chatId); // ✨ MIKA'S FIX: Isolate the save!
        });
    };
    // ✨ MIKA'S P.A.W.S. SPRITE GENERATOR ✨
