                        if (!targetChat) return next;

                        // ✨ MIKA'S FIX: Append the new tags to the original tags, removing duplicates, keeping up to 8 max!
                        const combinedTags = [...new Set([...originalTags, ...newTags])].slice(0, 8);

                        const updatedWaifu = {
                            ...targetChat.waifu,
                            original_tags: originalTags,
                            tags: combinedTags,
                            mutationLevel: direction
                        };

