            return { clean: clean.trim(), thought: thoughtStr.trim(), memory: memoryStr.trim(), location: locationStr.trim(), routineUpdate: routineUpdateStr.trim(), wardrobeAddition: wardrobeStr.trim(), dropVip: dropVipStr.trim() };
