                                    setDawState({ phase: 'active', concept: blankConcept, tags: '', originalTags: '', originalBpm: 120, structuredTags: { genre: [], instruments: [], vocals: [], vibe: [] }, isStructuredTags: true, lyrics: '', structuredLyrics: [], isStructuredLyrics: true, activeLyricDropdown: null, bpm: 120, duration: 60, isGenerating: false, progress: 0, status: '', audioUrl: null, expandedTagCat: null, expandedLyricId: null, isAiBusy: false, applyMastering: true, isSmartLength: true, isSmartBpm: true });
                                    setAppState('daw');
