                                                                const targetId = activeMeowModal.id;
                                                                showConfirm("Use Item?", `Are you sure you want to consume ${item}?`, () => {
                                                                    const sysMsg = { id: 'sys_inv_' + Date.now(), sender: 'System', text: `[SYSTEM_ACTION: ${activeMeowModal.name.split(' ')[0]} used ${item}!]`, isSystem: true, timestamp: Date.now() };
                                                                    setInbox(prev => {
                                                                        const next = { ...prev };
                                                                        let target = next[activeChatId]?.isGroup ? next[activeChatId].participants.find(p => p.id === targetId) : next[targetId]?.waifu;
                                                                        if (target && target.paws) {
                                                                            let inv = target.paws.inventory.split('|').map(i => i.trim()).filter(i => i);
                                                                            const rIdx = inv.findIndex(i => i === item);
                                                                            if (rIdx > -1) inv.splice(rIdx, 1);
                                                                            target.paws.inventory = inv.join(' | ');
                                                                            
                                                                            // Live-update the modal
                                                                            setActiveMeowModal(prevModal => {
                                                                                if (prevModal && prevModal.id === targetId) {
                                                                                    return { ...prevModal, paws: { ...prevModal.paws, inventory: target.paws.inventory } };
                                                                                }
                                                                                return prevModal;
                                                                            });
                                                                        }
                                                                        if (next[activeChatId]) next[activeChatId].messages = [...(next[activeChatId].messages || []), sysMsg];
                                                                        return next;
                                                                    });
                                                                    setTimeout(() => handleSaveSession(true), 100);
                                                                });
