                            <div>
                                <div style={{ color: '#fff', fontWeight: 'bold', fontSize: '16px', letterSpacing: '0.02em' }}>{activeChatStatsModal.waifu?.name}</div>
                                <div style={{ color: 'rgba(0,229,255,0.6)', fontSize: '10px', letterSpacing: '0.05em', marginTop: '2px' }}>AFFECTION SYNC: {activeChatStatsModal.affection}%</div>
                            </div>
